def mkdir_p(path: str | os.PathLike) -> None:
    Path(path).mkdir(parents=True, exist_ok=True)


def split_all(path: str | os.PathLike | None) -> Sequence[str] | None:
    """Split a path into a list of components

    While os.path.split() splits a single component off the back of
    `path`, this function splits all components:

    >>> split_all(os.path.join('a', 'b', 'c'))
    ('a', 'b', 'c')
    """
    if path is None:
        return None
    if isinstance(path, str):
        # Preserve historical behavior: strip leading "/" so an absolute path's
        # root is not treated as a component.
        path = Path(path.lstrip("/"))
    elif isinstance(path, pathlib.PurePath):
        pass
    else:
        raise TypeError(
            f'"path" was {type(path)}, must be string, None, or pathlib.Path'
        )

