def split_all(path: str | os.PathLike | None) -> Sequence[str] | None:
    """Split a path into a tuple of components.

    >>> split_all(Path('a', 'b', 'c'))
    ('a', 'b', 'c')
    """
    if path is None:
        return None
    if isinstance(path, str):
        # Preserve historical behavior: strip leading "/" so an absolute path's
        # root is not treated as a component.
        path = Path(path.lstrip("/"))
    elif isinstance(path, pathlib.PurePath):
        pass
    else:
        raise TypeError(
            f'"path" was {type(path)}, must be string, None, or pathlib.Path'
        )
    return path.parts

