        extensions are allowed)
    """
    if exclude is None:
        exclude = []
    # backward compatibility for older generators
    if isinstance(paths, str):
        paths = [paths]

    # group the exclude dir names by parent path, for use with os.walk()
    exclusions_by_dirpath = {}
    base = Path(self.path)
    for e in exclude:
        full = base / e
        exclusions_by_dirpath.setdefault(str(full.parent), set()).add(full.name)

    files = set()
    ignores = self.settings["IGNORE_FILES"]
    for path in paths:
        # careful: joining self.path with "" would add a trailing separator.
        root = base / path if path else base

        if root.is_dir():
            # os.walk is used because pathlib.Path.walk requires Python
            # 3.12+ and Pelican supports 3.11.
            for dirpath, dirs, temp_files in os.walk(
                root, topdown=True, followlinks=True
            ):
                excl = exclusions_by_dirpath.get(dirpath, ())
                # We copy the `dirs` list as we will modify it in the loop:
                for d in list(dirs):
                    if d in excl or any(
                        fnmatch.fnmatch(d, ignore) for ignore in ignores
                    ):
                        if d in dirs:
                            dirs.remove(d)

                reldir = Path(dirpath).relative_to(base)
                for f in temp_files:
                    fp = str(reldir / f)
                    if self._include_path(fp, extensions):
                        files.add(fp)
        elif root.exists() and self._include_path(path, extensions):
            files.add(path)  # can't walk non-directories
    return files

